package com.swaputil;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

final class Balances
{
	static List<Payment> payments(Ledger ledger, String settlement)
	{
		Map<List<String>, Payment> payments = new LinkedHashMap<>();
		for (Ledger.Trade trade : ledger.trades)
		{
			if (!settlement.equals(trade.settlement) || trade.partnerTransfer) { continue; }
			Fraction share = new Fraction(trade.received - trade.given, trade.participants.size());
			String operatorKey = Group.normalize(trade.operator);
			for (String partner : trade.participants)
			{
				String partnerKey = Group.normalize(partner);
				if (partnerKey.equals(operatorKey)) { continue; }
				boolean forward = operatorKey.compareTo(partnerKey) < 0;
				String first = forward ? trade.operator : partner;
				String second = forward ? partner : trade.operator;
				List<String> key = List.of(Group.normalize(first), Group.normalize(second), Integer.toString(trade.mode));
				Payment payment = payments.computeIfAbsent(key, ignored -> new Payment(first, second, trade.mode));
				payment.amount = payment.amount.add(forward ? share : share.negate());
			}
		}
		return new ArrayList<>(payments.values());
	}

	static List<Bucket> buckets(Ledger ledger, String settlement)
	{
		Map<List<String>, Bucket> buckets = new LinkedHashMap<>();
		for (Ledger.Trade trade : ledger.trades)
		{
			if (!settlement.equals(trade.settlement) || trade.partnerTransfer) { continue; }
			List<String> key = trade.participants.stream().map(Group::normalize).sorted().collect(Collectors.toList());
			key.add(0, trade.ratePeriod);
			Bucket bucket = buckets.computeIfAbsent(key, ignored -> new Bucket(trade.ratePeriod, trade.participants));
			bucket.given[trade.mode] = Math.addExact(bucket.given[trade.mode], trade.given);
			bucket.received[trade.mode] = Math.addExact(bucket.received[trade.mode], trade.received);
			bucket.count++;
		}
		return new ArrayList<>(buckets.values());
	}

	static final class Payment
	{
		final String first;
		final String second;
		final int mode;
		Fraction amount = Fraction.ZERO;
		Payment(String first, String second, int mode) { this.first = first; this.second = second; this.mode = mode; }
		String payer() { return amount.signum() >= 0 ? first : second; }
		String payee() { return amount.signum() >= 0 ? second : first; }
	}

	static final class Bucket
	{
		final String ratePeriod;
		final List<String> participants;
		final long[] received = new long[2];
		final long[] given = new long[2];
		int count;
		Bucket(String ratePeriod, List<String> participants)
		{
			this.ratePeriod = ratePeriod;
			this.participants = List.copyOf(participants);
		}
	}
}

package com.swaputil;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;

final class Fraction
{
	static final Fraction ZERO = new Fraction(BigInteger.ZERO, BigInteger.ONE);
	private final BigInteger numerator;
	private final BigInteger denominator;

	Fraction(long value, int divisor) { this(BigInteger.valueOf(value), BigInteger.valueOf(divisor)); }

	private Fraction(BigInteger numerator, BigInteger denominator)
	{
		if (denominator.signum() <= 0) { throw new IllegalArgumentException("Divisor must be positive"); }
		BigInteger gcd = numerator.gcd(denominator);
		this.numerator = numerator.divide(gcd);
		this.denominator = denominator.divide(gcd);
	}

	Fraction add(Fraction other)
	{
		return new Fraction(numerator.multiply(other.denominator).add(other.numerator.multiply(denominator)),
			denominator.multiply(other.denominator));
	}

	Fraction negate() { return new Fraction(numerator.negate(), denominator); }
	int signum() { return numerator.signum(); }
	BigDecimal rounded() { return new BigDecimal(numerator).divide(new BigDecimal(denominator), 0, RoundingMode.HALF_UP); }
}

package com.swaputil;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

final class Group
{
	private final Map<String, String> accounts = new LinkedHashMap<>();

	static String normalize(String name)
	{
		return name == null ? "" : name.replace('\u00a0', ' ').replace('_', ' ')
			.trim().replaceAll(" +", " ").toLowerCase(Locale.ROOT);
	}

	static Group parse(String text)
	{
		Group group = new Group();
		Set<String> people = new HashSet<>();
		for (String line : text.split("\\R"))
		{
			if (line.trim().isEmpty()) { continue; }
			String[] parts = line.split("=", -1);
			if (parts.length == 1) { parts = new String[]{line, line}; }
			if (parts.length != 2 || parts[0].trim().isEmpty() || parts[1].trim().isEmpty())
			{
				throw new IllegalArgumentException("Enter one RSN per line.");
			}
			String person = parts[0].trim();
			if (!people.add(normalize(person)))
			{
				throw new IllegalArgumentException("Each group member should appear only once.");
			}
			for (String account : parts[1].split(",", -1))
			{
				String key = normalize(account);
				if (key.isEmpty() || key.length() > 12 || !key.matches("[a-z0-9 -]+"))
				{
					throw new IllegalArgumentException("Enter a valid RSN on each line.");
				}
				if (group.accounts.putIfAbsent(key, person) != null)
				{
					throw new IllegalArgumentException("Each character can belong to only one person.");
				}
			}
		}
		return group;
	}

	String person(String account) { return accounts.get(normalize(account)); }

	List<String> participants(String account, Collection<String> online)
	{
		String owner = person(account);
		if (owner == null) { throw new IllegalArgumentException("Add this account to your group first."); }
		TreeSet<String> present = new TreeSet<>();
		present.add(owner);
		for (String name : online)
		{
			String partner = person(name);
			if (partner != null) { present.add(partner); }
		}
		return new ArrayList<>(present);
	}
}

package com.swaputil;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

final class Ledger
{
	int version = 1;
	long revision;
	String group = "";
	Map<String, Integer> accountModes = new LinkedHashMap<>();
	List<RatePeriod> rates = new ArrayList<>();
	List<Settlement> settlements = new ArrayList<>();
	List<Trade> trades = new ArrayList<>();

	Ledger()
	{
		rates.add(new RatePeriod("OSRS", "Hardcore", "900", "1500"));
		settlements.add(new Settlement());
	}

	RatePeriod rates() { return rates.get(rates.size() - 1); }
	Settlement current() { return settlements.get(settlements.size() - 1); }

	void configure(String groupText, String modeA, String modeB, String buy, String sell)
	{
		String nextGroup = groupText == null ? group : groupText.trim();
		Group.parse(nextGroup);
		RatePeriod current = rates();
		RatePeriod next = new RatePeriod(
			modeA == null ? current.modeA : modeA,
			modeB == null ? current.modeB : modeB,
			buy == null ? current.buy : buy,
			sell == null ? current.sell : sell);
		group = nextGroup;
		if (!rates().sameValues(next)) { rates.add(next); }
	}

	void setMode(String account, int mode)
	{
		if (Group.normalize(account).isEmpty() || mode < -1 || mode > 1)
		{
			throw new IllegalArgumentException("Select an account and mode.");
		}
		if (mode < 0) { accountModes.remove(Group.normalize(account)); }
		else { accountModes.put(Group.normalize(account), mode); }
	}

	void add(Trade trade)
	{
		if (trades.stream().anyMatch(t -> t.id.equals(trade.id))) { return; }
		if (trade.given < 0 || trade.received < 0 || trade.mode < 0 || trade.mode > 1
			|| trade.participants.isEmpty() || !trade.participants.contains(trade.operator)
			|| rates.stream().noneMatch(r -> r.id.equals(trade.ratePeriod)))
		{
			throw new IllegalArgumentException("Incomplete trade record.");
		}
		trade.settlement = current().id;
		trade.carriedForward = settlements.size() > 1 && trade.time < current().startedAt;
		trades.add(trade);
	}

	void settle(long expectedRevision)
	{
		checkRevision(expectedRevision);
		current().closedAt = System.currentTimeMillis();
		settlements.add(new Settlement());
	}

	void checkRevision(long expected)
	{
		if (revision != expected)
		{
			throw new IllegalStateException("Records changed in another client. Review the latest totals and try again.");
		}
	}

	static final class RatePeriod
	{
		String id = UUID.randomUUID().toString();
		long startedAt = System.currentTimeMillis();
		String modeA;
		String modeB;
		String buy;
		String sell;

		RatePeriod(String modeA, String modeB, String buy, String sell)
		{
			this.modeA = modeA.trim();
			this.modeB = modeB.trim();
			if (this.modeA.isEmpty() || this.modeB.isEmpty() || this.modeA.equalsIgnoreCase(this.modeB)
				|| this.modeA.length() > 24 || this.modeB.length() > 24)
			{
				throw new IllegalArgumentException("Enter two distinct mode names, up to 24 characters each.");
			}
			this.buy = rate(buy);
			this.sell = rate(sell);
		}

		private static String rate(String value)
		{
			try
			{
				BigDecimal rate = new BigDecimal(value.trim());
				if (rate.signum() <= 0 || rate.compareTo(new BigDecimal("1000000000000")) > 0 || rate.scale() > 8)
				{
					throw new NumberFormatException();
				}
				return rate.stripTrailingZeros().toPlainString();
			}
			catch (NumberFormatException ex)
			{
				throw new IllegalArgumentException("Rates must be positive numbers with up to 8 decimal places.");
			}
		}

		boolean sameValues(RatePeriod other)
		{
			return modeA.equals(other.modeA) && modeB.equals(other.modeB)
				&& buy.equals(other.buy) && sell.equals(other.sell);
		}

		String label(int mode) { return mode == 0 ? modeA : modeB; }
	}

	static final class Settlement
	{
		String id = UUID.randomUUID().toString();
		long startedAt = System.currentTimeMillis();
		long closedAt;
	}

	static final class Trade
	{
		String id = UUID.randomUUID().toString();
		long time = System.currentTimeMillis();
		String settlement;
		String ratePeriod;
		String account;
		String operator;
		String counterparty;
		int world;
		int mode;
		long given;
		long received;
		List<String> participants = new ArrayList<>();
		boolean partnerTransfer;
		boolean otherItems;
		boolean carriedForward;
	}
}

package com.swaputil;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.Reader;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.FileTime;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.client.util.Filepath;

final class LedgerStore
{
	private static final Object PROCESS_LOCK = new Object();
	private final Filepath directory;
	private final Gson gson;
	private Ledger cached;
	private long cachedSize;
	private FileTime cachedModified;

	LedgerStore(Filepath directory, Gson gson) { this.directory = directory; this.gson = gson; }
	Ledger read() throws IOException { return access(null); }
	Ledger update(Consumer<Ledger> change) throws IOException { return access(change); }

	private Ledger access(Consumer<Ledger> change) throws IOException
	{
		synchronized (PROCESS_LOCK)
		{
			directory.createDirectories();
			try (FileChannel channel = directory.join("ledger.lock").openFileChannel(
				StandardOpenOption.CREATE, StandardOpenOption.WRITE);
				FileLock lock = channel.lock())
			{
				Filepath file = directory.join("ledger.json");
				boolean exists = file.exists();
				if (change == null && cached != null && exists
					&& file.size() == cachedSize && file.getLastModifiedTime().equals(cachedModified))
				{
					return cached;
				}
				Ledger ledger;
				if (exists)
				{
					try (Reader reader = file.openReader()) { ledger = decode(reader); }
				}
				else { ledger = new Ledger(); }
				if (change != null) { change.accept(ledger); ledger.revision++; }
				if (!exists || change != null) { save(file, ledger); }
				cachedSize = file.size();
				cachedModified = file.getLastModifiedTime();
				cached = ledger;
				return ledger;
			}
		}
	}

	private Ledger decode(Reader json) throws IOException
	{
		try
		{
			JsonObject root = new JsonParser().parse(json).getAsJsonObject();
			for (String field : new String[]{"version", "revision", "group", "rates", "accountModes", "settlements", "trades"})
			{
				if (!root.has(field)) { throw new IllegalArgumentException("Missing ledger field: " + field); }
			}
			Ledger ledger = gson.fromJson(root, Ledger.class);
			if (ledger == null || ledger.version != 1 || ledger.group == null || ledger.accountModes == null
				|| ledger.rates == null || ledger.rates.isEmpty() || ledger.settlements == null
				|| ledger.settlements.isEmpty() || ledger.trades == null)
			{
				throw new IllegalArgumentException("Unsupported or incomplete ledger");
			}
			Group.parse(ledger.group);
			for (Integer mode : ledger.accountModes.values())
			{
				if (mode == null || mode < 0 || mode > 1) { throw new IllegalArgumentException("Invalid account mode"); }
			}
			if (ledger.current().closedAt != 0) { throw new IllegalArgumentException("No open settlement"); }
			Set<String> rates = new HashSet<>();
			for (Ledger.RatePeriod rate : ledger.rates)
			{
				new Ledger.RatePeriod(rate.modeA, rate.modeB, rate.buy, rate.sell);
				if (rate.id == null || !rates.add(rate.id)) { throw new IllegalArgumentException("Duplicate rate period"); }
			}
			Set<String> settlements = new HashSet<>();
			for (Ledger.Settlement settlement : ledger.settlements)
			{
				if (settlement.id == null || !settlements.add(settlement.id))
				{
					throw new IllegalArgumentException("Duplicate settlement");
				}
			}
			Set<String> ids = new HashSet<>();
			for (Ledger.Trade trade : ledger.trades)
			{
				if (trade == null || trade.id == null || !ids.add(trade.id) || trade.given < 0 || trade.received < 0
					|| trade.mode < 0 || trade.mode > 1 || !rates.contains(trade.ratePeriod)
					|| !settlements.contains(trade.settlement) || trade.participants == null
					|| !trade.participants.contains(trade.operator) || trade.participants.contains(null)
					|| new HashSet<>(trade.participants).size() != trade.participants.size()
					|| trade.account == null || trade.counterparty == null)
				{
					throw new IllegalArgumentException("Incomplete trade record");
				}
			}
			return ledger;
		}
		catch (JsonParseException | IllegalArgumentException | IllegalStateException | NullPointerException ex)
		{
			throw new IOException("Cannot read ledger.json. Existing records have been left untouched.", ex);
		}
	}

	private void save(Filepath file, Ledger ledger) throws IOException
	{
		Filepath temporary = directory.createTempFile("ledger-", ".tmp");
		try
		{
			byte[] bytes = gson.toJson(ledger).getBytes(StandardCharsets.UTF_8);
			try (FileChannel out = temporary.openFileChannel(StandardOpenOption.WRITE))
			{
				ByteBuffer buffer = ByteBuffer.wrap(bytes);
				while (buffer.hasRemaining()) { out.write(buffer); }
				out.force(true);
			}
			if (file.exists())
			{
				file.copyTo(directory.join("ledger.backup.json"), StandardCopyOption.REPLACE_EXISTING);
			}
			temporary.moveTo(file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		finally { temporary.deleteIfExists(); }
	}

	Filepath export() throws IOException
	{
		Ledger ledger = read();
		Filepath file = directory.createTempFile("swaputil-export-", ".json");
		file.write(gson.toJson(ledger));
		return file;
	}
}

package com.swaputil;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.math.BigDecimal;
import java.text.NumberFormat;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.DefaultCaret;
import javax.swing.text.JTextComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

final class SwapUtilPanel extends PluginPanel
{
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("MMM d HH:mm:ss").withZone(ZoneId.systemDefault());
	private final Consumer<Consumer<Ledger>> update;
	private final JTextArea status = text();
	private final JTextArea error = text();
	private final JComboBox<String> mode = new JComboBox<>();
	private final JTextArea summary = text();
	private final JTextArea payments = text();
	private final JTextArea buckets = text();
	private final JTextArea history = text();
	private final JComboBox<String> periods = new JComboBox<>();
	private final List<String> periodIds = new ArrayList<>();
	private final JTextField modeA = new JTextField();
	private final JTextField modeB = new JTextField();
	private final JTextField buy = new JTextField();
	private final JTextField sell = new JTextField();
	private final JComboBox<String> rateDirection = new JComboBox<>();
	private final JPanel rateFields = new JPanel(new CardLayout());
	private final JLabel rateUnit = new JLabel("Rate");
	private final Set<JTextComponent> edited = new HashSet<>();
	private final JTextArea group = new JTextArea(5, 16);
	private final JButton apply = new JButton("Save settings");
	private final JButton settle = new JButton("Mark settled");
	private Ledger ledger;
	private String account = "";
	private boolean rendering;
	private boolean busy;
	private boolean settingsSaving;
	private long shownRevision = -1;
	private String historySelection;
	private String notice = "";

	SwapUtilPanel(Consumer<Consumer<Ledger>> update, Runnable export)
	{
		this.update = update;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		JPanel top = column();
		addLine(top, status);
		addLine(top, mode);
		error.setForeground(new Color(255, 180, 110));
		addLine(top, error);
		add(top, BorderLayout.NORTH);

		JTabbedPane tabs = new JTabbedPane();
		JPanel overview = column();
		addLine(overview, summary);
		tabs.addTab("Totals", overview);

		JPanel setup = column();
		field(setup, "Mode A", modeA);
		field(setup, "Mode B", modeB);
		addLine(setup, new JLabel("Rate direction"));
		addLine(setup, rateDirection);
		addLine(setup, rateUnit);
		rateFields.add(rateRow(buy, true), "buy");
		rateFields.add(rateRow(sell, false), "sell");
		addLine(setup, rateFields);
		rateFields.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		addLine(setup, new JLabel("Group"));
		addLine(setup, note("Include yourself and your partners, one person per line.\nFor multiple accounts: Rang = hc rang, rang swaps"));
		group.setLineWrap(true);
		group.setWrapStyleWord(true);
		JScrollPane groupScroll = new JScrollPane(group);
		groupScroll.setPreferredSize(new Dimension(200, 100));
		addLine(setup, groupScroll);
		addLine(setup, apply);
		tabs.addTab("Setup", setup);

		JPanel records = column();
		addLine(records, periods);
		JButton exportButton = new JButton("Export records");
		addLine(records, exportButton);
		addLine(records, history);
		tabs.addTab("Log", records);

		JPanel splits = column();
		addLine(splits, new JLabel("To settle"));
		addLine(splits, payments);
		addLine(splits, settle);
		addLine(splits, new JLabel("Rate and attendance buckets"));
		addLine(splits, buckets);
		tabs.addTab("Split", splits);
		add(tabs, BorderLayout.CENTER);

		mode.addActionListener(event ->
		{
			if (rendering || ledger == null || account.isEmpty() || busy) { return; }
			String selectedAccount = account;
			int selectedMode = mode.getSelectedIndex() - 1;
			submit(data -> data.setMode(selectedAccount, selectedMode));
		});
		apply.addActionListener(event -> saveSettings());
		rateDirection.addActionListener(event ->
		{
			((CardLayout) rateFields.getLayout()).show(rateFields, rateDirection.getSelectedIndex() == 0 ? "buy" : "sell");
			rateUnit.setLabelFor(rateDirection.getSelectedIndex() == 0 ? buy : sell);
		});
		settle.addActionListener(event -> markSettled());
		exportButton.addActionListener(event -> export.run());
		periods.addActionListener(event ->
		{
			if (!rendering && periods.getSelectedIndex() >= 0)
			{
				historySelection = periodIds.get(periods.getSelectedIndex());
				renderHistory();
			}
		});
		for (JTextComponent field : List.of(modeA, modeB, buy, sell, group))
		{
			field.getDocument().addDocumentListener(new DocumentListener()
			{
				public void insertUpdate(DocumentEvent e) { changed(); }
				public void removeUpdate(DocumentEvent e) { changed(); }
				public void changedUpdate(DocumentEvent e) { changed(); }
				private void changed()
				{
					if (!rendering) { edited.add(field); }
				}
			});
		}
		status.setText("Loading local records...");
		mode.setEnabled(false);
		apply.setEnabled(false);
		settle.setEnabled(false);
	}

	void render(Ledger data, String currentAccount, String storageError)
	{
		ledger = data;
		account = currentAccount == null ? "" : currentAccount;
		setTextIfChanged(error, storageError.isEmpty() ? notice : storageError);
		error.setVisible(!error.getText().isEmpty());
		if (data == null) { return; }
		rendering = true;
		try
		{
			Ledger.RatePeriod rates = data.rates();
			Group people = Group.parse(data.group);
			Integer selectedMode = data.accountModes.get(Group.normalize(account));
			String owner = people.person(account);
			if (account.isEmpty()) { setTextIfChanged(status, "Log in to select this account's mode."); }
			else if (owner == null) { setTextIfChanged(status, "Add this account under Setup to start tracking."); }
			else if (selectedMode == null) { setTextIfChanged(status, "Select a mode to start tracking."); }
			else { setTextIfChanged(status, ""); }
			status.setVisible(!status.getText().isEmpty());
			String[] modes = {"Paused / select mode", rates.modeA, rates.modeB};
			if (mode.getItemCount() != 3 || !rates.modeA.equals(mode.getItemAt(1)) || !rates.modeB.equals(mode.getItemAt(2)))
			{
				mode.removeAllItems();
				for (String label : modes) { mode.addItem(label); }
			}
			mode.setSelectedIndex(selectedMode == null ? 0 : selectedMode + 1);
			mode.setEnabled(!account.isEmpty() && !busy && storageError.isEmpty());
			apply.setEnabled(!busy && storageError.isEmpty());
			settle.setEnabled(!busy && storageError.isEmpty() && data.trades.stream().anyMatch(t -> t.settlement.equals(data.current().id) && !t.partnerTransfer));
			syncField(modeA, rates.modeA);
			syncField(modeB, rates.modeB);
			syncField(buy, rates.buy);
			syncField(sell, rates.sell);
			syncField(group, data.group);
			String buyDirection = rates.modeB + " \u2192 " + rates.modeA;
			String sellDirection = rates.modeA + " \u2192 " + rates.modeB;
			if (rateDirection.getItemCount() != 2 || !buyDirection.equals(rateDirection.getItemAt(0))
				|| !sellDirection.equals(rateDirection.getItemAt(1)))
			{
				int selected = Math.max(0, rateDirection.getSelectedIndex());
				rateDirection.removeAllItems();
				rateDirection.addItem(buyDirection);
				rateDirection.addItem(sellDirection);
				rateDirection.setSelectedIndex(selected);
			}
			if (shownRevision != data.revision)
			{
				setTextIfChanged(summary, totals(data.current().id));
				setTextIfChanged(payments, paymentText(data.current().id));
				setTextIfChanged(buckets, bucketText(data.current().id));
				periodIds.clear();
				periods.removeAllItems();
				for (int i = data.settlements.size() - 1; i >= 0; i--)
				{
					Ledger.Settlement settlement = data.settlements.get(i);
					periodIds.add(settlement.id);
					periods.addItem((settlement.closedAt == 0 ? "Current: " : "Settled: ") + date(settlement.startedAt));
				}
				int selected = periodIds.indexOf(historySelection);
				periods.setSelectedIndex(Math.max(0, selected));
				historySelection = periodIds.get(periods.getSelectedIndex());
				renderHistory();
				shownRevision = data.revision;
			}
		}
		finally { rendering = false; }
	}

	private void saveSettings()
	{
		if (ledger == null || busy) { return; }
		String names = change(group);
		String a = change(modeA);
		String b = change(modeB);
		String buyValue = change(buy);
		String sellValue = change(sell);
		if (edited.isEmpty()) { return; }
		try
		{
			Group.parse(names == null ? ledger.group : names);
			Ledger.RatePeriod rates = ledger.rates();
			new Ledger.RatePeriod(a == null ? rates.modeA : a, b == null ? rates.modeB : b,
				buyValue == null ? rates.buy : buyValue, sellValue == null ? rates.sell : sellValue);
		}
		catch (IllegalArgumentException ex) { failure(ex.getMessage()); return; }
		settingsSaving = true;
		submit(data -> data.configure(names, a, b, buyValue, sellValue));
	}

	private String change(JTextComponent field) { return edited.contains(field) ? field.getText() : null; }

	private void syncField(JTextComponent field, String value)
	{
		if (!edited.contains(field)) { setTextIfChanged(field, value); }
	}

	private void enableSettings(boolean enabled)
	{
		for (JTextComponent field : List.of(modeA, modeB, buy, sell, group)) { field.setEditable(enabled); }
		rateDirection.setEnabled(enabled);
	}

	private void submit(Consumer<Ledger> action)
	{
		busy = true;
		enableSettings(false);
		apply.setEnabled(false);
		settle.setEnabled(false);
		mode.setEnabled(false);
		update.accept(action);
	}

	private void markSettled()
	{
		if (ledger == null || busy) { return; }
		long revision = ledger.revision;
		String message = paymentText(ledger.current().id) + "\n\nMark these payments as settled?";
		String[] options = {"Mark settled", "Cancel"};
		if (JOptionPane.showOptionDialog(this, message, "Mark settled", JOptionPane.DEFAULT_OPTION,
			JOptionPane.PLAIN_MESSAGE, null, options, options[1]) == 0)
		{
			submit(data -> data.settle(revision));
			historySelection = null;
		}
	}

	private String totals(String settlement)
	{
		long[] received = new long[2];
		long[] given = new long[2];
		int[] counts = new int[2];
		for (Ledger.Trade trade : ledger.trades)
		{
			if (!settlement.equals(trade.settlement) || trade.partnerTransfer) { continue; }
			received[trade.mode] = Math.addExact(received[trade.mode], trade.received);
			given[trade.mode] = Math.addExact(given[trade.mode], trade.given);
			counts[trade.mode]++;
		}
		StringBuilder result = new StringBuilder();
		if (ledger.trades.stream().anyMatch(t -> settlement.equals(t.settlement) && t.carriedForward && !t.partnerTransfer))
		{
			result.append("Includes a trade saved after the previous settlement.\n");
		}
		for (int mode = 0; mode < 2; mode++)
		{
			result.append('\n').append(ledger.rates().label(mode)).append("\nTrades: ").append(gp(counts[mode]))
				.append("\nReceived: ").append(gp(received[mode]))
				.append("\nGiven: ").append(gp(given[mode]))
				.append("\nNet: ").append(gp(received[mode] - given[mode])).append('\n');
		}
		return result.toString().trim();
	}

	private String paymentText(String settlement)
	{
		List<String> lines = new ArrayList<>();
		for (Balances.Payment payment : Balances.payments(ledger, settlement))
		{
			BigDecimal amount = payment.amount.rounded().abs();
			if (amount.signum() != 0)
			{
				lines.add(payment.payer() + " pays " + payment.payee() + "\n" + gp(amount) + " " + ledger.rates().label(payment.mode));
			}
		}
		return lines.isEmpty() ? "Nothing to settle." : String.join("\n\n", lines);
	}

	private String bucketText(String settlement)
	{
		List<String> lines = new ArrayList<>();
		for (Balances.Bucket bucket : Balances.buckets(ledger, settlement))
		{
			Ledger.RatePeriod rate = ledger.rates.stream().filter(r -> r.id.equals(bucket.ratePeriod)).findFirst().orElseThrow();
			StringBuilder text = new StringBuilder(date(rate.startedAt) + "\nRates " + rate.buy + " / " + rate.sell
				+ "\n" + String.join(", ", bucket.participants) + "\n" + bucket.count + " trades");
			for (int mode = 0; mode < 2; mode++)
			{
				text.append('\n').append(rate.label(mode)).append(": +").append(gp(bucket.received[mode]))
					.append(" / -").append(gp(bucket.given[mode]));
			}
			lines.add(text.toString());
		}
		return lines.isEmpty() ? "No customer trades yet." : String.join("\n\n", lines);
	}

	private void renderHistory()
	{
		if (ledger == null || historySelection == null) { return; }
		setTextIfChanged(history, totals(historySelection) + "\n\n" + paymentText(historySelection)
			+ "\n\n" + bucketText(historySelection));
	}

	void saved()
	{
		busy = false;
		enableSettings(true);
		if (settingsSaving) { edited.clear(); settingsSaving = false; }
		notice = "";
	}

	void failure(String message)
	{
		busy = false;
		enableSettings(true);
		settingsSaving = false;
		notice = message == null ? "Unable to save changes." : message;
		error.setText(notice);
		apply.setEnabled(ledger != null);
	}

	void exported(String path)
	{
		JOptionPane.showMessageDialog(this, "Records saved to:\n" + path, "Export records",
			JOptionPane.PLAIN_MESSAGE);
	}

	private static JPanel column()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		return panel;
	}

	private static JPanel rateRow(JTextField field, boolean receivingModeB)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.add(field, BorderLayout.CENTER);
		row.add(new JLabel(receivingModeB ? "1 :" : ": 1"), receivingModeB ? BorderLayout.WEST : BorderLayout.EAST);
		return row;
	}

	private static JTextArea text()
	{
		JTextArea area = new JTextArea(0, 18)
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		area.setEditable(false);
		((DefaultCaret) area.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setOpaque(false);
		area.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return area;
	}

	private static void setTextIfChanged(JTextComponent component, String value)
	{
		if (!value.equals(component.getText())) { component.setText(value); }
	}

	private static JTextArea note(String value)
	{
		JTextArea area = text();
		area.setText(value);
		area.setOpaque(true);
		area.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		area.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		return area;
	}

	private static void addLine(JPanel panel, JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		int maxHeight = component instanceof JScrollPane ? 100
			: component instanceof JTextField || component instanceof JComboBox || component instanceof JButton ? 30
			: component instanceof JLabel ? component.getPreferredSize().height : Integer.MAX_VALUE;
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, maxHeight));
		panel.add(component);
		panel.add(Box.createVerticalStrut(8));
	}

	private static void field(JPanel panel, String label, JTextField field)
	{
		JLabel title = new JLabel(label);
		title.setLabelFor(field);
		addLine(panel, title);
		addLine(panel, field);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
	}

	static String gp(Number value) { return NumberFormat.getIntegerInstance(Locale.US).format(value); }
	static String date(long millis) { return DATE.format(Instant.ofEpochMilli(millis)); }
}

package com.swaputil;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "SwapUtil",
	internalName = "swaputil",
	legacyDataDirectory = "swaputil",
	description = "Tracks currency swaps, partner shares and settlements",
	tags = {"trade", "swap", "gp", "tracker"}
)
public class SwapUtilPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(SwapUtilPlugin.class);
	private static final int OTHER_OFFER = InventoryID.TRADEOFFER | 0x8000;
	@Inject private Client client;
	@Inject private ClientToolbar toolbar;
	@Inject private Gson gson;
	private final TradeCapture capture = new TradeCapture();
	private final Queue<Ledger.Trade> pending = new ConcurrentLinkedQueue<>();
	private volatile Ledger ledger;
	private volatile String account = "";
	private volatile boolean running;
	private LedgerStore store;
	private ScheduledExecutorService worker;
	private SwapUtilPanel panel;
	private NavigationButton navigation;
	private String storageError = "";

	@Override
	protected void startUp() throws IOException
	{
		store = new LedgerStore(getPluginDirectory(), gson);
		running = true;
		worker = Executors.newSingleThreadScheduledExecutor(task ->
		{
			Thread thread = new Thread(task, "swaputil-storage");
			thread.setDaemon(true);
			return thread;
		});
		SwingUtilities.invokeLater(() ->
		{
			if (!running) { return; }
			panel = new SwapUtilPanel(this::update, this::export);
			navigation = NavigationButton.builder().tooltip("SwapUtil")
				.icon(ImageUtil.loadImageResource(getClass(), "icon.png")).panel(panel).priority(6).build();
			toolbar.addNavigation(navigation);
		});
		worker.scheduleWithFixedDelay(this::refresh, 0, 1, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		running = false;
		capture.clear();
		account = "";
		if (worker != null) { worker.execute(this::flush); worker.shutdown(); }
		SwingUtilities.invokeLater(() ->
		{
			if (navigation != null) { toolbar.removeNavigation(navigation); }
			panel = null;
		});
	}

	private void flush()
	{
		try
		{
			Ledger.Trade trade;
			while ((trade = pending.peek()) != null)
			{
				Ledger.Trade next = trade;
				ledger = store.update(data -> data.add(next));
				pending.remove(next);
			}
		}
		catch (IOException | RuntimeException ex) { error(ex); }
	}

	private void refresh()
	{
		if (!running) { return; }
		flush();
		try
		{
			ledger = store.read();
			if (pending.isEmpty()) { storageError = ""; }
		}
		catch (IOException | RuntimeException ex) { error(ex); }
		Ledger snapshot = ledger;
		String currentAccount = account;
		String error = storageError;
		SwingUtilities.invokeLater(() ->
		{
			if (running && panel != null) { panel.render(snapshot, currentAccount, error); }
		});
	}

	private void error(Exception ex)
	{
		String message = "Records could not be saved or loaded. " + (pending.isEmpty() ? "" : pending.size() + " trade(s) waiting. ")
			+ "Check the SwapUtil folder and client log.";
		if (!message.equals(storageError)) { log.warn("SwapUtil storage failure", ex); }
		storageError = message;
	}

	private void update(Consumer<Ledger> change)
	{
		worker.execute(() ->
		{
			flush();
			try
			{
				if (!pending.isEmpty()) { throw new IllegalStateException("Wait for pending trades to save before making changes."); }
				ledger = store.update(change);
				SwingUtilities.invokeLater(() -> { if (panel != null) { panel.saved(); } });
			}
			catch (IOException | RuntimeException ex)
			{
				log.warn("Could not update SwapUtil records", ex);
				SwingUtilities.invokeLater(() -> { if (panel != null) { panel.failure(ex.getMessage()); } });
			}
			refresh();
		});
	}

	private void export()
	{
		worker.execute(() ->
		{
			try
			{
				flush();
				if (!pending.isEmpty()) { throw new IOException("Some trades have not been saved yet."); }
				String path = store.export().toString();
				SwingUtilities.invokeLater(() -> { if (panel != null) { panel.exported(path); } });
			}
			catch (IOException ex)
			{
				SwingUtilities.invokeLater(() -> { if (panel != null) { panel.failure(ex.getMessage()); } });
			}
		});
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (worker != null && !worker.isShutdown()) { event.waitFor(worker.submit(this::flush)); }
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		account = player == null ? "" : player.getName();
		capture.tick(client.getTickCount());
		readOpponent();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING
			|| event.getGameState() == GameState.CONNECTION_LOST)
		{
			capture.clear();
			account = "";
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!running) { return; }
		if (event.getGroupId() == InterfaceID.TRADEMAIN)
		{
			Player player = client.getLocalPlayer();
			if (player == null) { return; }
			capture.begin(ledger, player.getName(), client.getWorld());
			readOffers();
			readOpponent();
		}
		else if (event.getGroupId() == InterfaceID.TRADECONFIRM)
		{
			readOffers();
			readOpponent();
			capture.confirm();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.TRADEMAIN || event.getGroupId() == InterfaceID.TRADECONFIRM)
		{
			capture.closed(event.getGroupId() == InterfaceID.TRADECONFIRM, client.getTickCount());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.TRADEOFFER || event.getContainerId() == OTHER_OFFER)
		{
			capture.offer(event.getContainerId() == InventoryID.TRADEOFFER, event.getItemContainer().getItems());
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!running || event.getType() != ChatMessageType.TRADE) { return; }
		if ("Accepted trade.".equals(event.getMessage()))
		{
			Ledger.Trade trade = capture.complete(onlineMembers(), System.currentTimeMillis());
			if (trade != null)
			{
				pending.add(trade);
				worker.execute(this::refresh);
			}
		}
		else if ("Other player declined trade.".equals(event.getMessage())) { capture.clear(); }
	}

	private void readOffers()
	{
		ItemContainer given = client.getItemContainer(InventoryID.TRADEOFFER);
		ItemContainer received = client.getItemContainer(OTHER_OFFER);
		if (given != null) { capture.offer(true, given.getItems()); }
		if (received != null) { capture.offer(false, received.getItems()); }
	}

	private void readOpponent()
	{
		Widget widget = client.getWidget(InterfaceID.Trademain.TITLE);
		if (widget == null || widget.isHidden()) { widget = client.getWidget(InterfaceID.Tradeconfirm.TRADEOPPONENT); }
		if (widget == null || widget.isHidden()) { return; }
		String text = Text.removeTags(widget.getText()).replace('\u00a0', ' ').trim();
		String name = text.replaceFirst("(?i)^Trading with:\\s*", "");
		if (!name.equals(text)) { capture.opponent(name); }
	}

	private List<String> onlineMembers()
	{
		List<String> names = new ArrayList<>();
		FriendsChatManager chat = client.getFriendsChatManager();
		if (chat != null)
		{
			for (FriendsChatMember member : chat.getMembers())
			{
				if (member.getWorld() > 0) { names.add(member.getName()); }
			}
		}
		return names;
	}
}

package com.swaputil;

import java.util.Collection;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

final class TradeCapture
{
	private Ledger.Trade trade;
	private Group group;
	private boolean confirmation;
	private int closedAt = -1;
	private boolean givenItems;
	private boolean receivedItems;

	void begin(Ledger ledger, String account, int world)
	{
		clear();
		if (ledger == null) { return; }
		group = Group.parse(ledger.group);
		String operator = group.person(account);
		Integer mode = ledger.accountModes.get(Group.normalize(account));
		if (operator == null || mode == null) { return; }
		trade = new Ledger.Trade();
		trade.account = account;
		trade.operator = operator;
		trade.world = world;
		trade.mode = mode;
		trade.ratePeriod = ledger.rates().id;
	}

	void opponent(String name)
	{
		if (trade != null && !name.isEmpty()) { trade.counterparty = name; }
	}

	void offer(boolean given, Item[] items)
	{
		if (trade == null || confirmation || closedAt >= 0) { return; }
		long gp = 0;
		boolean other = false;
		for (Item item : items)
		{
			if (item == null || item.getId() < 0 || item.getQuantity() <= 0) { continue; }
			if (item.getId() == ItemID.COINS) { gp += item.getQuantity(); }
			else if (item.getId() == ItemID.PLATINUM) { gp += item.getQuantity() * 1000L; }
			else { other = true; }
		}
		if (given) { trade.given = gp; givenItems = other; }
		else { trade.received = gp; receivedItems = other; }
	}

	void confirm()
	{
		confirmation = true;
		closedAt = -1;
	}

	void closed(boolean confirmationScreen, int tick)
	{
		if (confirmationScreen == confirmation) { closedAt = tick; }
	}
	void tick(int tick) { if (closedAt >= 0 && tick - closedAt > 2) { clear(); } }

	Ledger.Trade complete(Collection<String> online, long time)
	{
		Ledger.Trade result = trade;
		if (result == null || !confirmation || result.counterparty == null
			|| (result.given == 0 && result.received == 0))
		{
			clear();
			return null;
		}
		result.time = time;
		result.participants = group.participants(result.account, online);
		result.partnerTransfer = group.person(result.counterparty) != null;
		result.otherItems = givenItems || receivedItems;
		clear();
		return result;
	}

	void clear()
	{
		trade = null;
		group = null;
		confirmation = false;
		closedAt = -1;
		givenItems = false;
		receivedItems = false;
	}
}

package com.swaputil;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class LedgerStoreTest
{
	@Rule public TemporaryFolder temporary = new TemporaryFolder();

	private static LedgerStore store(Path path)
	{
		return new LedgerStore(Filepath.Unchecked.getRooted(path), new Gson());
	}

	private static Ledger exported(LedgerStore store) throws IOException
	{
		try (Reader reader = store.export().openReader())
		{
			return new Gson().fromJson(reader, Ledger.class);
		}
	}

	@Test
	public void cachedReaderSeesOtherClientsChangesAndExportsThem() throws Exception
	{
		Path path = temporary.newFolder().toPath();
		LedgerStore reader = store(path);
		LedgerStore writer = store(path);
		assertEquals("900", reader.read().rates().buy);
		writer.update(ledger -> ledger.configure(null, null, null, "950", null));
		assertEquals("950", reader.read().rates().buy);
		writer.update(ledger -> LedgerTest.trade(ledger, "Me", 0, 0, 100, "Me"));
		assertEquals(1, reader.read().trades.size());
		Ledger exported = exported(reader);
		assertEquals(1, exported.trades.size());
		assertEquals("950", exported.rates().buy);
	}

	@Test
	public void independentRateWritesMergeUnderTheFileLock() throws Exception
	{
		Path path = temporary.newFolder().toPath();
		LedgerStore first = store(path);
		LedgerStore second = store(path);
		first.read();
		second.read();
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try
		{
			Future<Ledger> buy = executor.submit(() -> first.update(ledger -> ledger.configure(null, null, null, "1000", null)));
			Future<Ledger> sell = executor.submit(() -> second.update(ledger -> ledger.configure(null, null, null, null, "1100")));
			buy.get();
			sell.get();
		}
		finally { executor.shutdown(); }
		Ledger result = first.read();
		assertEquals("1000", result.rates().buy);
		assertEquals("1100", result.rates().sell);
		assertEquals(3, result.rates.size());
		assertEquals("900", result.rates.get(0).buy);
		assertEquals("1500", result.rates.get(0).sell);
	}

	@Test
	public void twoClientsShareRatesAndDoNotLoseEachOthersWrites() throws Exception
	{
		Path path = temporary.newFolder().toPath();
		LedgerStore first = store(path);
		LedgerStore second = store(path);
		first.update(ledger -> ledger.group = LedgerTest.configured().group);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try
		{
			Future<?> a = executor.submit(() -> append(first));
			Future<?> b = executor.submit(() -> append(second));
			a.get();
			b.get();
		}
		finally { executor.shutdown(); }
		assertEquals(40, first.read().trades.size());
		assertEquals(40, second.read().trades.size());
		assertTrue(Files.exists(path.resolve("ledger.backup.json")));
		assertEquals(41, first.read().revision);
	}

	private void append(LedgerStore store)
	{
		for (int i = 0; i < 20; i++)
		{
			try { store.update(ledger -> LedgerTest.trade(ledger, "Me", 0, 0, 100, "Alex", "Me")); }
			catch (IOException ex) { throw new RuntimeException(ex); }
		}
	}

	@Test
	public void failedMutationDoesNotOverwriteRecords() throws Exception
	{
		Path path = temporary.newFolder().toPath();
		LedgerStore store = store(path);
		store.read();
		String before = Files.readString(path.resolve("ledger.json"));
		try
		{
			store.update(ledger -> { ledger.group = "bad"; throw new IllegalArgumentException("invalid"); });
			fail();
		}
		catch (IllegalArgumentException expected) { }
		assertEquals(before, Files.readString(path.resolve("ledger.json")));
		assertEquals("", store.read().group);
	}

	@Test
	public void corruptFileIsNeverReplacedWithAnEmptyLedger() throws Exception
	{
		Path path = temporary.newFolder().toPath();
		LedgerStore store = store(path);
		store.read();
		Files.writeString(path.resolve("ledger.json"), "broken");
		try { store.read(); fail(); }
		catch (IOException expected) { assertTrue(expected.getMessage().contains("untouched")); }
		assertEquals("broken", Files.readString(path.resolve("ledger.json")));
	}

	@Test
	public void incompleteJsonCannotSilentlyResetTheLedger() throws Exception
	{
		Path path = temporary.newFolder().toPath();
		LedgerStore store = store(path);
		Files.writeString(path.resolve("ledger.json"), "{}");
		try { store.read(); fail(); }
		catch (IOException expected) { assertTrue(expected.getMessage().contains("untouched")); }
		assertEquals("{}", Files.readString(path.resolve("ledger.json")));
	}

	@Test
	public void exportIncludesArchivedTradesWithoutResettingAnything() throws Exception
	{
		LedgerStore store = store(temporary.newFolder().toPath());
		store.update(ledger -> LedgerTest.trade(ledger, "Me", 0, 0, 100, "Me"));
		store.update(ledger -> ledger.settle(ledger.revision));
		Ledger exported = exported(store);
		assertEquals(1, exported.trades.size());
		assertEquals(2, exported.settlements.size());
		assertEquals(store.read().revision, exported.revision);
	}
}

package com.swaputil;

import java.math.BigDecimal;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class LedgerTest
{
	static Ledger configured()
	{
		Ledger ledger = new Ledger();
		ledger.group = "Me = My main, My alt\nAlex = Alex main, Alex alt\nSam = Sam main\nPat = Pat main";
		ledger.setMode("My main", 0);
		ledger.setMode("My alt", 1);
		return ledger;
	}

	static Ledger.Trade trade(Ledger ledger, String owner, int mode, long given, long received, String... people)
	{
		Ledger.Trade trade = new Ledger.Trade();
		trade.account = "My main";
		trade.operator = owner;
		trade.counterparty = "Customer";
		trade.mode = mode;
		trade.given = given;
		trade.received = received;
		trade.ratePeriod = ledger.rates().id;
		trade.participants = List.of(people);
		ledger.add(trade);
		return trade;
	}

	@Test
	public void dividesBothSidesWithoutConvertingCurrencies()
	{
		Ledger ledger = configured();
		trade(ledger, "Me", 0, 0, 100_000_000, "Alex", "Me");
		trade(ledger, "Me", 1, 1_300_000_000L, 0, "Alex", "Me");
		List<Balances.Payment> payments = Balances.payments(ledger, ledger.current().id);
		assertEquals(2, payments.size());
		assertEquals("Me", payments.get(0).payer());
		assertEquals("Alex", payments.get(0).payee());
		assertEquals(new BigDecimal("50000000"), payments.get(0).amount.rounded().abs());
		assertEquals("Alex", payments.get(1).payer());
		assertEquals("Me", payments.get(1).payee());
		assertEquals(new BigDecimal("650000000"), payments.get(1).amount.rounded().abs());
	}

	@Test
	public void offsetsOppositeObligationsAcrossOperators()
	{
		Ledger ledger = configured();
		trade(ledger, "Me", 0, 0, 100, "Alex", "Me");
		trade(ledger, "Alex", 0, 0, 40, "Alex", "Me");
		Balances.Payment payment = Balances.payments(ledger, ledger.current().id).get(0);
		assertEquals("Me", payment.payer());
		assertEquals(new BigDecimal("30"), payment.amount.rounded().abs());
	}

	@Test
	public void capitalisationChangesDoNotSplitTheSamePeopleIntoDifferentBalances()
	{
		Ledger ledger = configured();
		trade(ledger, "My main", 0, 0, 100, "Alex main", "My main");
		trade(ledger, "alex_main", 0, 0, 40, "MY MAIN", "alex_main");
		List<Balances.Payment> payments = Balances.payments(ledger, ledger.current().id);
		assertEquals(1, payments.size());
		assertEquals("My main", payments.get(0).payer());
		assertEquals(new BigDecimal("30"), payments.get(0).amount.rounded().abs());
		assertEquals(1, Balances.buckets(ledger, ledger.current().id).size());
		assertEquals(2, Balances.buckets(ledger, ledger.current().id).get(0).count);
	}

	@Test
	public void retainsFractionsAcrossManyThreeWayTrades()
	{
		Ledger ledger = configured();
		for (int i = 0; i < 300; i++) { trade(ledger, "Me", 0, 0, 1, "Alex", "Me", "Sam"); }
		for (Balances.Payment payment : Balances.payments(ledger, ledger.current().id))
		{
			assertEquals(new BigDecimal("100"), payment.amount.rounded().abs());
		}
	}

	@Test
	public void keepsGrossVolumeWhenNetIsZero()
	{
		Ledger ledger = configured();
		trade(ledger, "Me", 0, 100, 0, "Me");
		trade(ledger, "Me", 0, 0, 100, "Me");
		Balances.Bucket bucket = Balances.buckets(ledger, ledger.current().id).get(0);
		assertEquals(100, bucket.received[0]);
		assertEquals(100, bucket.given[0]);
		assertTrue(Balances.payments(ledger, ledger.current().id).isEmpty());
	}

	@Test
	public void partnerTransfersDoNotAffectCustomerVolumeOrShares()
	{
		Ledger ledger = configured();
		Ledger.Trade transfer = trade(ledger, "Me", 0, 0, 100, "Alex", "Me");
		transfer.partnerTransfer = true;
		assertTrue(Balances.buckets(ledger, ledger.current().id).isEmpty());
		assertTrue(Balances.payments(ledger, ledger.current().id).isEmpty());
		assertEquals(1, ledger.trades.size());
	}

	@Test
	public void startsNewRatePeriodsEvenWhenReturningToPreviousRates()
	{
		Ledger ledger = configured();
		Ledger.Trade first = trade(ledger, "Me", 0, 0, 100, "Alex", "Me");
		ledger.configure(ledger.group, "OSRS", "Hardcore", "1000", "1100");
		trade(ledger, "Me", 0, 0, 100, "Alex", "Me");
		ledger.configure(ledger.group, "OSRS", "Hardcore", "900", "1500");
		trade(ledger, "Me", 0, 0, 100, "Alex", "Me");
		assertEquals(3, ledger.rates.size());
		assertEquals(3, Balances.buckets(ledger, ledger.current().id).size());
		assertEquals(ledger.rates.get(0).id, first.ratePeriod);
		assertNotEquals(first.ratePeriod, ledger.rates().id);
	}

	@Test
	public void unchangedRatesDoNotCreatePeriod()
	{
		Ledger ledger = configured();
		ledger.configure(ledger.group, "OSRS", "Hardcore", "900.00", "1500");
		assertEquals(1, ledger.rates.size());
	}

	@Test
	public void settlementPreservesHistoryAndRates()
	{
		Ledger ledger = configured();
		trade(ledger, "Me", 0, 0, 100, "Alex", "Me");
		String previous = ledger.current().id;
		String rates = ledger.rates().id;
		ledger.settle(0);
		assertEquals(1, ledger.trades.size());
		assertTrue(ledger.settlements.get(0).closedAt > 0);
		assertTrue(Balances.payments(ledger, ledger.current().id).isEmpty());
		assertEquals(1, Balances.payments(ledger, previous).size());
		assertEquals(rates, ledger.rates().id);
	}

	@Test
	public void lateSaveCarriesUnaccountedTradeIntoTheNewSettlement()
	{
		Ledger ledger = configured();
		Ledger.Trade late = new Ledger.Trade();
		late.account = "My main";
		late.operator = "Me";
		late.counterparty = "Customer";
		late.mode = 0;
		late.received = 100;
		late.ratePeriod = ledger.rates().id;
		late.participants = List.of("Alex", "Me");
		late.time = 1;
		ledger.settle(0);
		ledger.add(late);
		assertTrue(late.carriedForward);
		assertEquals(ledger.current().id, late.settlement);
		assertEquals(1, Balances.payments(ledger, ledger.current().id).size());
	}

	@Test
	public void incomingTradesDoNotPreventSettingsChanges()
	{
		Ledger ledger = configured();
		ledger.revision = 10;
		ledger.configure(ledger.group, "OSRS", "Hardcore", "1000", "1100");
		assertEquals("1100", ledger.rates().sell);
	}

	@Test
	public void independentRateUpdatesPreserveTheOtherClientsChanges()
	{
		Ledger ledger = configured();
		String group = ledger.group;
		String originalPeriod = ledger.rates().id;
		ledger.configure(null, null, null, "1000", null);
		ledger.configure(null, null, null, null, "1100");
		assertEquals("1000", ledger.rates().buy);
		assertEquals("1100", ledger.rates().sell);
		assertEquals(group, ledger.group);
		assertEquals(3, ledger.rates.size());
		assertEquals(originalPeriod, ledger.rates.get(0).id);
		assertEquals("900", ledger.rates.get(0).buy);
		assertEquals("1500", ledger.rates.get(0).sell);
	}

	@Test(expected = IllegalStateException.class)
	public void refusesSettlementAfterAnotherClientChangesRecords()
	{
		Ledger ledger = configured();
		ledger.revision = 5;
		ledger.settle(4);
	}

	@Test
	public void duplicateTradeIsOnlyAddedOnce()
	{
		Ledger ledger = configured();
		Ledger.Trade trade = trade(ledger, "Me", 0, 0, 100, "Me");
		ledger.add(trade);
		assertEquals(1, ledger.trades.size());
	}

	@Test
	public void deduplicatesAltsAndIgnoresUnlistedFriendsChatMembers()
	{
		Group group = Group.parse(configured().group);
		assertEquals(List.of("Alex", "Me"), group.participants("MY_MAIN", List.of("My alt", "Alex main", "Alex alt", "Stranger")));
		assertEquals(List.of("Me"), group.participants("My main", List.of()));
	}

	@Test(expected = IllegalArgumentException.class)
	public void refusesAmbiguousAliases()
	{
		Group.parse("Alex = Alex_main\nSam = alex main");
	}

	@Test
	public void acceptsOneRsnPerLine()
	{
		Group group = Group.parse("Rang swaps\n\nAlex main\nSam main");
		assertEquals("Rang swaps", group.person("rang_swaps"));
		assertEquals(List.of("Alex main", "Rang swaps"),
			group.participants("Rang swaps", List.of("ALEX MAIN", "Stranger")));
		assertEquals(List.of("Rang swaps"), group.participants("Rang swaps", List.of()));
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsDuplicateRsnsRegardlessOfCaseOrSpaces()
	{
		Group.parse("Rang swaps\nRANG_SWAPS");
	}

	@Test
	public void preservesIndependentAccountModes()
	{
		Ledger ledger = configured();
		assertEquals(Integer.valueOf(0), ledger.accountModes.get("my main"));
		assertEquals(Integer.valueOf(1), ledger.accountModes.get("my alt"));
		ledger.setMode("My main", -1);
		assertFalse(ledger.accountModes.containsKey("my main"));
		assertEquals(Integer.valueOf(1), ledger.accountModes.get("my alt"));
	}
}

package com.swaputil;

import java.awt.Component;
import java.awt.Container;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.SwingUtilities;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.DefaultCaret;
import javax.swing.text.JTextComponent;
import org.junit.Test;
import static org.junit.Assert.*;

public class SidebarRefreshTest
{
	@Test
	public void twoClientsSaveDifferentRatesWithoutOverwritingEachOther() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			Ledger shared = LedgerTest.configured();
			Gson gson = new Gson();
			SwapUtilPanel first = new SwapUtilPanel(action -> action.accept(shared), () -> {});
			SwapUtilPanel second = new SwapUtilPanel(action -> action.accept(shared), () -> {});
			first.render(gson.fromJson(gson.toJson(shared), Ledger.class), "My main", "");
			second.render(gson.fromJson(gson.toJson(shared), Ledger.class), "My alt", "");
			JComboBox<?> firstDirection = direction(first);
			JComboBox<?> secondDirection = direction(second);
			firstDirection.setSelectedIndex(0);
			secondDirection.setSelectedIndex(1);
			fieldWithValue(first, "900").setText("1000");
			fieldWithValue(second, "1500").setText("1100");
			saveButton(first).doClick();
			assertEquals("1000", shared.rates().buy);
			assertEquals("1500", shared.rates().sell);
			second.render(gson.fromJson(gson.toJson(shared), Ledger.class), "My alt", "");
			assertEquals(1, secondDirection.getSelectedIndex());
			assertNotNull(fieldWithValue(second, "1100"));
			saveButton(second).doClick();
			assertEquals("1000", shared.rates().buy);
			assertEquals("1100", shared.rates().sell);
			assertEquals(LedgerTest.configured().group, shared.group);
			assertEquals(Integer.valueOf(0), shared.accountModes.get("my main"));
			assertEquals(Integer.valueOf(1), shared.accountModes.get("my alt"));
			first.saved();
			first.render(gson.fromJson(gson.toJson(shared), Ledger.class), "My main", "");
			assertEquals(0, firstDirection.getSelectedIndex());
		});
	}

	@Test
	public void rateSavePreservesAnUnseenPartnerUpdate() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			Ledger shared = LedgerTest.configured();
			SwapUtilPanel panel = new SwapUtilPanel(action -> action.accept(shared), () -> {});
			panel.render(new Gson().fromJson(new Gson().toJson(shared), Ledger.class), "My main", "");
			fieldWithValue(panel, "900").setText("950");
			String newGroup = shared.group + "\nNew partner = New alt";
			shared.configure(newGroup, null, null, null, "1600");
			saveButton(panel).doClick();
			assertEquals(newGroup, shared.group);
			assertEquals("950", shared.rates().buy);
			assertEquals("1600", shared.rates().sell);
		});
	}

	private static JTextComponent fieldWithValue(Container parent, String value)
	{
		return fields(parent).stream().filter(field -> field.isEditable() && value.equals(field.getText())).findFirst().orElseThrow();
	}

	private static JComboBox<?> direction(Container parent)
	{
		return (JComboBox<?>) components(parent).stream().filter(component -> component instanceof JComboBox
			&& ((JComboBox<?>) component).getItemCount() == 2
			&& "Hardcore \u2192 OSRS".equals(((JComboBox<?>) component).getItemAt(0))).findFirst().orElseThrow();
	}

	private static JButton saveButton(Container parent)
	{
		return (JButton) components(parent).stream().filter(component -> component instanceof JButton
			&& "Save settings".equals(((JButton) component).getText())).findFirst().orElseThrow();
	}

	private static List<Component> components(Container parent)
	{
		List<Component> result = new ArrayList<>();
		for (Component child : parent.getComponents())
		{
			result.add(child);
			if (child instanceof Container) { result.addAll(components((Container) child)); }
		}
		return result;
	}

	@Test
	public void unchangedRefreshPreservesDocumentsAndTextSelection() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			Ledger ledger = LedgerTest.configured();
			SwapUtilPanel panel = new SwapUtilPanel(action -> {}, () -> {});
			panel.render(ledger, "My main", "");
			AtomicInteger edits = new AtomicInteger();
			List<JTextComponent> fields = fields(panel);
			for (JTextComponent field : fields)
			{
				field.select(0, field.getDocument().getLength());
				field.getDocument().addDocumentListener(new DocumentListener()
				{
					public void insertUpdate(DocumentEvent event) { edits.incrementAndGet(); }
					public void removeUpdate(DocumentEvent event) { edits.incrementAndGet(); }
					public void changedUpdate(DocumentEvent event) { edits.incrementAndGet(); }
				});
			}
			for (int i = 0; i < 5; i++) { panel.render(ledger, "My main", ""); }
			assertEquals(0, edits.get());
			for (JTextComponent field : fields)
			{
				assertEquals(field.getDocument().getLength(), field.getSelectionEnd());
			}
		});
	}

	@Test
	public void displayingAnErrorDoesNotAskTheViewportToFollowItsCaret() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			Ledger ledger = LedgerTest.configured();
			SwapUtilPanel panel = new SwapUtilPanel(action -> {}, () -> {});
			panel.render(ledger, "My main", "");
			panel.render(ledger, "My main", "Could not save records.");
			for (JTextComponent field : fields(panel))
			{
				if (!field.isEditable())
				{
					assertEquals(DefaultCaret.NEVER_UPDATE, ((DefaultCaret) field.getCaret()).getUpdatePolicy());
				}
			}
			assertTrue(fields(panel).stream().anyMatch(field -> field.getText().equals("Could not save records.")));
		});
	}

	private static List<JTextComponent> fields(Container parent)
	{
		List<JTextComponent> result = new ArrayList<>();
		for (Component child : parent.getComponents())
		{
			if (child instanceof JTextComponent) { result.add((JTextComponent) child); }
			else if (child instanceof Container) { result.addAll(fields((Container) child)); }
		}
		return result;
	}
}

